512:export async function vmStatus(vmid: number): Promise<any> {
589: * fallback. In SANDBOX returns a synthetic, gently-varying realistic value.
599:  if (SANDBOX) {

490	 * via a node-scoped client. `storage` defaults to "backup" — the primary's own
491	 * real (legacy, pre-multi-node) archive storage id — but every node onboarded
492	 * via the current scripts/onboard-node.sh names its backup-content storage
493	 * after its `Node.storageHdd` value instead (e.g. node-2's "vmdata-hdd", which
494	 * does carry Proxmox's "backup" content type even though the *name* differs
495	 * from primary's). Confirmed live 2026-09-05: hardcoding "backup" here made
496	 * every provision onto node-2 fail outright ("storage 'backup' does not
497	 * exist") — the two nodes' storage NAMING diverged even though their intent
498	 * (one dir/zfspool for backup archives + templates) is the same.
499	 */
500	export async function archivedVmids(client: TaskClient, storage = "backup"): Promise<Set<number>> {
501	  const content: StorageBackupEntry[] = await client.get(
502	    `/nodes/${client.node}/storage/${storage}/content`,
503	    { content: "backup" }
504	  );
505	  const out = new Set<number>();
506	  for (const b of content ?? []) {
507	    if (typeof b?.vmid === "number" && Number.isInteger(b.vmid)) out.add(b.vmid);
508	  }
509	  return out;
510	}
511	
512	export async function vmStatus(vmid: number): Promise<any> {
513	  return pve.get(`/nodes/${NODE}/qemu/${vmid}/status/current`);
514	}
515	
516	/** Pass a specific node's connection (e.g. `pveForNode(node)`) to query a
517	 *  non-primary node — falls back to the primary singleton when omitted. */
518	export async function nodeStatus(conn?: PveClient): Promise<any> {
519	  const c = conn ?? pve;
520	  const node = conn ? conn.node : NODE;
521	  return c.get(`/nodes/${node}/status`);
522	}
523	
524	export async function listVms(conn?: PveClient): Promise<any[]> {
525	  const c = conn ?? pve;
526	  const node = conn ? conn.node : NODE;
527	  return c.get(`/nodes/${node}/qemu`);
528	}
529	
530	/** Time-series metrics. timeframe: hour | day | week | month | year.
531	 *  Pass the server's node connection — vmids can collide across nodes, so a
532	 *  same-numbered VM on another node would otherwise leak that tenant's series. */
