import { NextResponse } from "next/server";
import { db } from "@/lib/db";
import { currentUser } from "@/lib/auth";
import { vmStatus, pveForNode } from "@/lib/proxmox";
import { readBwMeterHealth, bwUsageView } from "@/lib/bandwidth";
import { NO_STORE_HEADERS } from "@/app/api/_lib/no-store";

export const dynamic = "force-dynamic";

/**
 * Real "Resource Usage — across all services" numbers for the dashboard's
 * donut widget (components/nx/ResourceUsageCard.tsx).
 *
 * This is its own round trip, fetched client-side AFTER the dashboard shell
 * paints, because CPU/Memory need one live Proxmox call per provisioned VM —
 * exactly the round-trip cost app/dashboard/page.tsx's old TODO comment
 * flagged, and the reason this never became an `await` in that page. Storage
 * and Network read data the worker/other pages already collect, so they cost
 * nothing extra here.
 */

type Metric = { measured: boolean; pct: number };

export async function GET() {
  const user = await currentUser();
  if (!user) {
    return NextResponse.json({ error: "unauthorized" }, { status: 401, headers: NO_STORE_HEADERS });
  }

  // Same "All Services" scope the rest of this dashboard uses for this
  // widget's own table — VPS + game-server rows (db.server), not Shared
  // Hosting or a free Minecraft server, which don't carry per-VM Proxmox
  // stats or the same bandwidth counters. See app/dashboard/page.tsx's own
  // comment on `filters` for why that scoping is deliberate, not an oversight.
  const servers = await db.server.findMany({
    where: { userId: user.id, status: { not: "DELETING" } },
    select: {
      id: true,
      vmid: true,
      status: true,
      bwInBytes: true,
      bwOutBytes: true,
      bwWindowStart: true,
      plan: { select: { cpuCores: true, ramMB: true, bandwidthTB: true } },
      gamePlan: { select: { cpuCores: true, ramMB: true } },
      node: true,
    },
  });

  // ---- CPU + Memory: one live status/current call per provisioned VM. ----
  // A STOPPED VM answers this call fine, with real zeroed cpu/mem and its real
  // maxmem — that's genuine live data (a customer who turned a box off really
  // is using 0% of it right now), so it is included exactly like a RUNNING
  // one rather than special-cased. The only thing dropped is an actual
  // failure: the vmid doesn't exist on the hypervisor (a staging/sandbox row,
  // or a deleted VM the DB hasn't caught up on) or the node is unreachable.
  // Those are silently excluded from the sums — never guessed at — the same
  // "an API error is our blind spot, not the customer's" rule worker/uptime.ts
  // already applies.
  const withVmid = servers.filter((s) => s.vmid != null);
  const liveResults = await Promise.allSettled(
    withVmid.map((s) =>
      s.node ? pveForNode(s.node).vmStatus(s.vmid as number) : vmStatus(s.vmid as number)
    )
  );

  // Weighted by each VM's own real capacity (cores / bytes of RAM), not a
  // naive average of percentages — a maxed-out 1-vCPU box and an idle 8-vCPU
  // box are not "50% CPU" between them.
  let usedCoreEquiv = 0;
  let totalCores = 0;
  let usedMemBytes = 0;
  let totalMemBytes = 0;

  liveResults.forEach((r, i) => {
    if (r.status !== "fulfilled" || !r.value) return;
    const s = withVmid[i];
    const cores = s.gamePlan?.cpuCores ?? s.plan.cpuCores;
    const cpuFrac = Math.max(0, Number(r.value.cpu) || 0);
    if (cores > 0) {
      usedCoreEquiv += cpuFrac * cores;
      totalCores += cores;
    }
    const maxmem = Math.max(0, Number(r.value.maxmem) || 0);
    if (maxmem > 0) {
      usedMemBytes += Math.min(maxmem, Math.max(0, Number(r.value.mem) || 0));
      totalMemBytes += maxmem;
    }
  });

  const cpu: Metric = totalCores > 0
    ? { measured: true, pct: Math.min(100, (usedCoreEquiv / totalCores) * 100) }
    : { measured: false, pct: 0 };
  const memory: Metric = totalMemBytes > 0
    ? { measured: true, pct: Math.min(100, (usedMemBytes / totalMemBytes) * 100) }
    : { measured: false, pct: 0 };

  // ---- Storage: the latest worker-collected guest-agent sample per server
  // (ServerDiskSample, sampled every ~10 minutes — worker/monitor.ts's
  // sampleServerDisks). Deliberately NOT a live get-fsinfo call here: Proxmox
  // RRD/status report `disk: 0` for every QEMU VM regardless of real usage
  // (confirmed against this box's own live cluster resources), so the only
  // real number comes from the guest agent, and a fresh-enough one is already
  // sitting in the DB without a second per-VM round trip stacked on the one
  // above. */
  const diskSamples = await Promise.all(
    servers.map((s) =>
      db.serverDiskSample.findFirst({
        where: { serverId: s.id },
        orderBy: { ts: "desc" },
        select: { usedBytes: true, totalBytes: true },
      })
    )
  );
  let usedDiskBytes = 0;
  let totalDiskBytes = 0;
  for (const sample of diskSamples) {
    if (!sample || sample.totalBytes <= 0n) continue;
    usedDiskBytes += Number(sample.usedBytes);
    totalDiskBytes += Number(sample.totalBytes);
  }
  const storage: Metric = totalDiskBytes > 0
    ? { measured: true, pct: Math.min(100, (usedDiskBytes / totalDiskBytes) * 100) }
    : { measured: false, pct: 0 };

  // ---- Network: the exact same metered counters and 30-day rolling window
  // the Billing page's Bandwidth card reads (lib/bandwidth.ts) — one source
  // of truth for "how much has this server actually moved", not a second,
  // possibly-drifting formula invented here. ----
  const bwHealth = await readBwMeterHealth();
  let usedBwBytes = 0;
  let allowanceBwBytes = 0;
  let bwMeasuredAny = false;
  let bwPartialAny = false;
  let earliestMeasuredFrom: Date | null = null;
  for (const s of servers) {
    const view = bwUsageView(s, s.plan.bandwidthTB * 1e12, bwHealth);
    if (!view.measured) continue;
    bwMeasuredAny = true;
    usedBwBytes += view.usedBytes;
    if (view.allowanceBytes > 0) allowanceBwBytes += view.allowanceBytes;
    if (view.partial) bwPartialAny = true;
    if (view.measuredFrom && (!earliestMeasuredFrom || view.measuredFrom < earliestMeasuredFrom)) {
      earliestMeasuredFrom = view.measuredFrom;
    }
  }
  const network = {
    measured: bwMeasuredAny,
    pct: bwMeasuredAny && allowanceBwBytes > 0 ? Math.min(100, (usedBwBytes / allowanceBwBytes) * 100) : 0,
    usedBytes: usedBwBytes,
    partial: bwPartialAny,
    sinceIso: earliestMeasuredFrom ? earliestMeasuredFrom.toISOString() : null,
  };

  return NextResponse.json({ cpu, memory, storage, network }, { headers: NO_STORE_HEADERS });
}

