"use client";

import { useEffect, useState } from "react";
import { Icon } from "./Icon";
import { Donut } from "./Bits";
import { Ribbons } from "./Ribbons";
import { fmtBytes } from "@/components/ui/primitives";

type Metric = { measured: boolean; pct: number };
type Payload = {
  cpu: Metric;
  memory: Metric;
  storage: Metric;
  network: Metric & { usedBytes: number; partial: boolean; sinceIso: string | null };
};

/* Cosmetic per-ring identity only — every real number comes from the fetch
   below. Kept as a constant here rather than server props because none of it
   is data: the label and gradient never change no matter whose dashboard
   this is. */
const RING_META = {
  cpu: { label: "CPU", from: "#3fbcd8", to: "#2f7eef" },
  memory: { label: "Memory", from: "#6f37d6", to: "#c026d3" },
  storage: { label: "Storage", from: "#d623e1", to: "#6f2ee0" },
  network: { label: "Network", from: "#14c5e4", to: "#11c88e" },
} as const;

/**
 * The dashboard's "Resource Usage — across all services" card.
 *
 * Self-contained on purpose: CPU/Memory need one live Proxmox round trip PER
 * provisioned VM, which is slow enough that awaiting it in
 * app/dashboard/page.tsx would hold up the entire page's first paint. This
 * fetches /api/dashboard/resource-usage after mount instead — the dashboard
 * shell (stats, service table, activity feed) renders immediately, and these
 * four rings fill in a moment later. Same pattern as this dashboard's
 * NetworkStatusModal fetching /api/dashboard/network-status on open.
 */
export function ResourceUsageCard() {
  const [data, setData] = useState<Payload | null>(null);
  const [failed, setFailed] = useState(false);

  useEffect(() => {
    let live = true;
    fetch("/api/dashboard/resource-usage", { cache: "no-store" })
      .then((r) => (r.ok ? r.json() : Promise.reject(new Error(`HTTP ${r.status}`))))
      .then((d: Payload) => { if (live) setData(d); })
      .catch(() => { if (live) setFailed(true); });
    return () => { live = false; };
  }, []);

  // Loading placeholder: empty rings, no fabricated numbers while the real
  // fetch is in flight. `failed` (the fetch itself errored, e.g. a network
  // blip in the browser) renders the same honest "—" as "measured: false" —
  // both mean "nothing real to show right now", never a guess.
  const metrics = (["cpu", "memory", "storage", "network"] as const).map((key) => {
    const meta = RING_META[key];
    const m = data?.[key];
    const measured = !failed && !!m?.measured;
    const pct = measured ? m!.pct : 0;
    const value = !measured
      ? "—"
      : key === "network"
        ? fmtBytes((data!.network as Payload["network"]).usedBytes)
        : `${Math.round(pct)}%`;
    return { key, label: meta.label, from: meta.from, to: meta.to, pct, value };
  });

  const net = data?.network;
  const periodLabel = !data
    ? null // still loading — no static/interactive label to show yet either
    : failed || !net?.measured
      ? "Not measured yet"
      : net.partial && net.sinceIso
        ? `Since ${new Date(net.sinceIso).toLocaleDateString("en-US", { month: "short", day: "numeric" })}`
        : "Last 30 days";

  return (
    <section className="relative z-10 card relative isolate flex flex-none flex-col items-start gap-3 overflow-hidden px-3.5 pb-6 pt-2.5 sm:flex-row sm:items-center sm:gap-6">
      <div aria-hidden
           className="pointer-events-none absolute inset-x-0 bottom-0 -z-10 h-[62%] opacity-[0.72]"
           style={{ WebkitMaskImage: "linear-gradient(180deg, transparent 0%, #000 40%, #000 88%, transparent 100%)",
                    maskImage: "linear-gradient(180deg, transparent 0%, #000 40%, #000 88%, transparent 100%)" }}>
        <Ribbons />
      </div>

      <div className="flex w-[150px] flex-none flex-col gap-1">
        <h2 className="text-[12px] font-bold uppercase tracking-[0.17em] text-white">
          Resource Usage
        </h2>
        <span className="text-[11px] text-tx-faint">Across all services</span>
      </div>
      {/* Two-up on a phone. Four donuts across 390px collided into a
          single unreadable smear ("42%68%37%2.4TB" on one line, the labels
          stacked on each other) — measured, not guessed. */}
      <div className="grid flex-1 grid-cols-2 items-start gap-3 sm:grid-cols-4 sm:gap-2">
        {metrics.map((u) => <Donut key={u.key} {...u} size={46} />)}
      </div>
      {/* Real label, not a working control: the platform meters bandwidth on
          a single rolling 30-day window (lib/bandwidth.ts) — there is no
          second stored period to switch to, so this used to be a "30D"
          button with no onClick at all. Naming what's actually shown beats
          a toggle that looks functional and isn't. */}
      {periodLabel && (
        <span
          className="flex h-[30px] flex-none cursor-default items-center gap-1.5 whitespace-nowrap rounded-full border border-rim-hi bg-surface px-3 text-[11.5px] font-semibold text-tx-dim"
          title="Network usage is metered on a single rolling 30-day window — there's no other period to switch to yet."
        >
          <Icon name="clock" size={10} /> {periodLabel}
        </span>
      )}
    </section>
  );
}

