content.content:
---
---nginx-conf---
        internal;
    }
    location / {
        proxy_pass http://127.0.0.1:3001;
        proxy_http_version 1.1;
        proxy_set_header Host $host;
        proxy_set_header X-Real-IP $remote_addr;
        proxy_set_header X-Forwarded-For $proxy_add_x_forwarded_for;
        proxy_set_header X-Forwarded-Proto $scheme;
        proxy_set_header Upgrade $http_upgrade;
        proxy_set_header Connection "upgrade";
        # Some Server Actions do real SSH/provisioning work and can
        # legitimately run past nginx's 60s default — without this,
        # nginx serves maintenance.html mid-request and breaks the
        # client's Server Action response parsing. Confirmed live 2026-09-02.
        proxy_read_timeout 600s;
        proxy_send_timeout 600s;
    }
}
# Direct-IP :8080 fallback (self-signed on :8443 handled elsewhere)
server {
    listen 8080 default_server;

